import type { ArizeAvailability } from "./types.js";

const DEFAULT_ENDPOINT = "https://otlp.arize.com/v1/traces";
const MAX_CONTENT_CHARS = 16_000;
const MAX_RATE_LIMIT = 300;

export interface ArizeServerConfig extends ArizeAvailability {
  apiKey?: string;
  spaceId?: string;
  endpoint?: string;
  projectName?: string;
}

function boundedInteger(value: string | undefined, fallback: number, max: number): number {
  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed > 0 ? Math.min(parsed, max) : fallback;
}

function validEndpoint(value: string): boolean {
  try {
    const parsed = new URL(value);
    return (parsed.protocol === "https:" || parsed.protocol === "http:") && Boolean(parsed.hostname);
  } catch {
    return false;
  }
}

function validProjectName(value: string): boolean {
  return value.length > 0 && value.length <= 128 && /^[A-Za-z0-9][A-Za-z0-9._ -]*$/.test(value);
}

/** Reads only server/local environment. Never expose this structure to a client. */
export function readArizeConfig(env: NodeJS.ProcessEnv = process.env): ArizeServerConfig {
  const enabledByOperator = env.ARIZE_ENABLED === "true";
  const apiKey = env.ARIZE_API_KEY?.trim();
  const spaceId = env.ARIZE_SPACE_ID?.trim();
  const endpoint = (env.ARIZE_OTLP_ENDPOINT?.trim() || DEFAULT_ENDPOINT);
  const projectName = (env.ARIZE_PROJECT_NAME?.trim() || "keating");
  const evaluationContentEnabled = env.ARIZE_EVALUATION_CONTENT_ENABLED === "true";
  const maxContentChars = boundedInteger(env.ARIZE_MAX_CONTENT_CHARS, MAX_CONTENT_CHARS, MAX_CONTENT_CHARS);
  const rateLimitPerMinute = boundedInteger(env.ARIZE_RATE_LIMIT_PER_MINUTE, 30, MAX_RATE_LIMIT);

  let reason: ArizeServerConfig["reason"] = "enabled";
  if (!enabledByOperator) reason = "disabled";
  else if (!apiKey) reason = "missing_api_key";
  else if (!spaceId) reason = "missing_space_id";
  else if (!validEndpoint(endpoint)) reason = "invalid_endpoint";
  else if (!validProjectName(projectName)) reason = "invalid_project_name";

  return {
    enabled: reason === "enabled",
    reason,
    evaluationContentEnabled,
    maxContentChars,
    rateLimitPerMinute,
    ...(reason === "enabled" ? { apiKey, spaceId, endpoint, projectName } : {}),
  };
}

export function publicArizeAvailability(config = readArizeConfig()): ArizeAvailability {
  return {
    enabled: config.enabled,
    reason: config.reason,
    evaluationContentEnabled: config.evaluationContentEnabled,
    maxContentChars: config.maxContentChars,
    rateLimitPerMinute: config.rateLimitPerMinute,
  };
}

import { SpanStatusCode } from "@opentelemetry/api";
import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-proto";
import { resourceFromAttributes } from "@opentelemetry/resources";
import { NodeTracerProvider } from "@opentelemetry/sdk-trace-node";

import { readArizeConfig } from "./config.js";
import type { EvaluationObservationV1 } from "./types.js";

type ObservationExporter = (observation: EvaluationObservationV1) => Promise<void>;

let testExporter: ObservationExporter | undefined;

export function setEvaluationObservationExporterForTests(exporter?: ObservationExporter): void {
  testExporter = exporter;
}

function attributesFor(observation: EvaluationObservationV1): Record<string, string | number | boolean> {
  const attributes: Record<string, string | number | boolean> = {
    "openinference.span.kind": "EVALUATOR",
    "keating.schema.version": observation.schemaVersion,
    "keating.evidence.engine": observation.engine,
    "keating.evaluation.status": observation.status,
    "keating.evaluation.suite": observation.suite,
    "keating.duration_ms": observation.duration_ms,
    "keating.app.version": observation.app_version,
    "keating.surface": observation.surface,
  };
  for (const key of ["score", "before_score", "after_score", "outcome_count", "candidate_count"] as const) {
    if (observation[key] !== undefined) attributes[`keating.evaluation.${key}`] = observation[key];
  }
  if (observation.provider) attributes["llm.provider"] = observation.provider;
  if (observation.model) attributes["llm.model_name"] = observation.model;
  if (observation.error_category) attributes["keating.error.category"] = observation.error_category;
  return attributes;
}

async function exportToOtlp(observation: EvaluationObservationV1): Promise<void> {
  const config = readArizeConfig();
  if (!config.enabled || !config.apiKey || !config.spaceId || !config.endpoint || !config.projectName) return;

  const exporter = new OTLPTraceExporter({
    url: config.endpoint,
    headers: { "arize-space-id": config.spaceId, "arize-api-key": config.apiKey },
  });
  const provider = new NodeTracerProvider({
    resource: resourceFromAttributes({ "openinference.project.name": config.projectName }),
    spanProcessors: [{
      onStart: () => undefined,
      onEnd: (span) => { void exporter.export([span], () => undefined); },
      shutdown: () => exporter.shutdown(),
      forceFlush: () => Promise.resolve(),
    }],
  });
  const span = provider.getTracer("keating.arize").startSpan(`keating.evaluation.${observation.operation}`);
  span.setAttributes(attributesFor(observation));
  if (observation.status !== "success") span.setStatus({ code: SpanStatusCode.ERROR, message: observation.error_category ?? observation.status });
  span.end();
  await provider.forceFlush();
  await provider.shutdown();
}

/** Best effort by contract: a telemetry outage must never alter the caller. */
export async function exportEvaluationObservation(observation: EvaluationObservationV1): Promise<void> {
  try {
    if (testExporter) await testExporter(observation);
    else await exportToOtlp(observation);
  } catch {
    // Intentionally opaque: raw transport/provider errors may contain secrets.
  }
}

export function classifyObservationError(error: unknown): string {
  if (error instanceof Error && /not ready|cooldown/i.test(error.message)) return "rejected";
  if (error instanceof Error && /parse|json/i.test(error.message)) return "parse";
  return "operation_failed";
}

